#!/usr/bin/env python3
"""Real keyboard / virtual Gamepad API controls, WebGL2 and WebAudio; prepared sea/weather."""
from browser_support import Browser, ROOT
import time,json,hashlib
with Browser() as b:
 b.cmd('Page.addScriptToEvaluateOnNewDocument',{'source':'''window.virtualPad={id:'Xbox 360 Controller (STANDARD GAMEPAD)',index:0,connected:true,mapping:'standard',axes:[0,0,0,0],buttons:Array.from({length:17},()=>({value:0,pressed:false}))};Object.defineProperty(navigator,'getGamepads',{value:()=>[virtualPad]});'''})
 b.load();ev=b.ev;ev('RADE.game.start();globalThis.s=RADE.game.session;globalThis.m=s.marine;s.weather.tick=()=>{s.weather.state.wind=.8;s.weather.state.gust=.2;s.weather.state.windDirection=0;return [];};true');checks=[];measurements={}
 def key(code,seconds=.12):
  b.cmd('Input.dispatchKeyEvent',{'type':'keyDown','code':code,'key':code.removeprefix('Key').lower()});time.sleep(seconds);b.cmd('Input.dispatchKeyEvent',{'type':'keyUp','code':code,'key':code.removeprefix('Key').lower()});time.sleep(.15)
 def button(i,value=1):ev(f'virtualPad.buttons[{i}].value={value};virtualPad.buttons[{i}].pressed={str(value>.5).lower()};true')
 def tap(i):button(i);time.sleep(.13);button(i,0);time.sleep(.18)
 def board(kind):
  ev('''m.leave();m.boats.forEach((q,i)=>Object.assign(q,{x:-8100-i*25,z:5000,speed:0}));globalThis.q=m.boats.find(q=>q.kind==='''+json.dumps(kind)+''');Object.assign(q,{x:-8000,z:5000,cap:Math.PI/2,speed:0,sailAngle:.73,sailDeployment:0,sailTrim:0,engineOn:q.kind!=='sailboat'});Object.assign(s.player,{x:q.x,z:q.z,y:0,yaw:0,pitch:0});m.enterWater(s.player);true''');key('KeyE');b.wait('s.mode==="boat"&&m.boat===q')
 board('sailboat');ev('RADE.game.recorder.start("Voilier · postes, manivelles et auxiliaire");true');assert ev('!q.engineOn&&q.engineRpm===0');b.wait('RADE.game.engineSound.stats().gainMoteur<.002');assert not ev('document.getElementById("sailing").hidden');assert ev('document.getElementById("compass-degrees").textContent.length>2')
 key('KeyC');assert ev('q.control==="trim"');angle=ev('q.sailAngle');key('KeyA',.9);assert ev('q.sailAngle')<angle-.2;key('KeyD',.9);checks.append('C sélectionne orientation ; A/D tournent réellement la manivelle et la voile')
 tap(3);assert ev('q.control==="hoist"');button(7,.65);time.sleep(1.2);button(7,0);time.sleep(.15);deployed=ev('q.sailDeployment');assert .05<deployed<.35,deployed;button(6,.7);time.sleep(.6);button(6,0);time.sleep(.15);assert ev('q.sailDeployment')<deployed-.03;checks.append('Y sélectionne déploiement ; RT/LT analogiques hissent et affalent')
 key('KeyW',5);b.wait('q.sailDeployment>.98&&q.speed>1');tap(3);assert ev('q.control==="helm"');cap=ev('q.cap');key('KeyD',.8);assert abs(ev('q.cap')-cap)>.02;assert ev('q.catch>0');assert ev('!q.engineOn&&q.engineRpm===0');b.wait('RADE.game.engineSound.stats().gainMoteur<.002');b.capture('sailing-helm.png');measurements['sail']=ev('({speed:q.speed,catch:q.catch,angle:q.sailAngle,deployment:q.sailDeployment,audio:RADE.game.engineSound.stats(),hud:document.getElementById("sail-summary").textContent})');checks.append('Voile pleine et portée : déplacement au vent, gouvernail effectif, moteur joueur silencieux')
 # Stop the wind for a separate auxiliary-engine demonstration, using the same keyboard controls.
 ev('s.weather.tick=()=>{s.weather.state.wind=0;s.weather.state.gust=0;s.weather.state.windDirection=0;return [];};true');key('KeyC');key('KeyC');assert ev('q.control==="hoist"');key('KeyS',5);assert ev('q.sailDeployment<.02');key('KeyC');key('KeyF');assert ev('q.engineOn');key('KeyW',1.5);b.wait('RADE.game.engineSound.stats().gainMoteur>.002');measurements['auxiliary']=ev('({speed:q.speed,engineRpm:q.engineRpm,audio:RADE.game.engineSound.stats()})');key('KeyF');b.wait('!q.engineOn&&q.engineRpm===0&&RADE.game.engineSound.stats().gainMoteur<.002');checks.append('F démarre/arrête le petit moteur ; régime et gain WebAudio suivent son état')
 tape=ev('RADE.game.recorder.stop()');tape['source']='tests/sailing-browser.py — keyboard and virtual standard Gamepad API';(ROOT/'docs/sailing-recording.json').write_text(json.dumps(tape,separators=(',',':'))+'\n')
 for kind in ['motorboat','jetski']:
  board(kind);before=ev('({x:q.x,z:q.z})');key('KeyW',1.5);assert ev('q.speed>1&&q.engineOn&&q.engineRpm>=750');b.wait('RADE.game.engineSound.stats().gainMoteur>.002');measurements[kind]=ev('({speed:q.speed,audio:RADE.game.engineSound.stats(),x:q.x,z:q.z})');assert abs(measurements[kind]['x']-before['x'])+abs(measurements[kind]['z']-before['z'])>.5;b.capture('sailing-'+kind+'.png')
 checks.append('Canot et jet-ski : accélération clavier, déplacement mesuré et moteur audible via gain WebAudio')
 assert not ev('RADE.game.errors');report={'checks':checks,'measurements':measurements,'metrics':ev('RADE.game.metrics()'),'errors':ev('RADE.game.errors'),'fixture':'Positions en pleine mer et météo contrôlées ; clavier réel, Gamepad API virtuelle (aucune manette physique). Gain audio mesuré, aucune écoute humaine revendiquée.','buildSha256':hashlib.sha256((ROOT/'dist/index.html').read_bytes()).hexdigest()};(ROOT/'docs/sailing-browser.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps(report,ensure_ascii=False,indent=2),flush=True)
